\label{Lem:ManyDuals}
Suppose that $\sigma \subset S$ is a birecurrent track.  Then
$\mathcal{C}^*(\sigma)$ has infinite diameter inside of $\mathcal{C}(S)$.

\label{Clm:Accumulation}
The point $x$ is an accumulation point of $\partial (\mathbb{H} {\smallsetminus}
\mathcal{H}_{x,y})$.

\label{Lem:Slide}
There is a constant $A = A(S)$ so that if $\{ \tau_i \}_{i = 1}^N$ is
an injective sliding sequence in $\mathcal{T}(S)$ then $N + 1 \leq A$. \qed

\cite[Theorem~1.1]{MasurMinsky99}
\label{Thm:Hyperbolic}
For every connected compact orientable surface $X$ there is a constant
$\delta_X$ so that $\mathcal{C}(X)$ is $\delta_X$--hyperbolic.

\label{Lem:Disjoint}
If $I \subset J_X$ is disjoint from all inductive subintervals of
$J_X$ then $I$ is straight for $X$.

\label{Lem:Straight}
There is a constant $A = A(X)$, independent of $\{ \tau_i \}$, so that
if $I \subset J_X$ is straight then $|\mathcal{S}_X(I)| \leq_A d_X(I)$.

\label{Clm:Jump}
Fix $n \in [0,M-2]$.  Let $\tau, \sigma = \tau_{\rho(n)},
\tau_{\rho(n+1)}$.  Then $d_X(\tau, \sigma) \geq {\sf R_0} + 1$.

\label{Def:Short}
A straight subinterval $I$ for $X$ is {\em short} if $d_X(I) \leq
4{\sf R_0}$.  Otherwise $I$ is {\em long}.

\label{Lem:Nested}
If $Z \in {\sf Ind}$ then 
\[
\operatorname{card} \big\{ Y \in {\sf Ind} \mathbin{\mid} Z \subset Y,\,\xi(Z) < \xi(Y) \big\} 
    \leq 2(\xi(X) - \xi(Z) - 1).
\]
